        [/^Цохилтоор (\d+) амь хаслаа\.$/, 'Your strike dealt $1 damage.'],
        [/^Ундаа ууж (\d+) амь нөхлөө\.$/, 'The potion restored $1 HP.'],
        [/^Дайсны (шид|дайралт) (\d+) амь хаслаа\.$/, (_, move, hp) => 'The enemy’s ' + (move === 'шид' ? 'spell' : 'attack') + ' dealt ' + hp + ' damage.'],
        [/^(\d+) ээлж дууслаа\. Цохилт хийх боломжоо хайгаарай\.$/, 'All $1 turns are up. Look for an opening to strike.'],
        [/^Дайсанд (\d+) амь үлдлээ\. Коддоо дараагийн үйлдлээ нэмж бичээрэй\.$/, 'The enemy has $1 HP left. Add your next action.'],
        [/^(Ялалт!|Бүх тулаанд яллаа!) (\+\d+ XP\.)$/, (_, win, xp) => GameLocale.text(win) + ' ' + xp],
        [/^(Ялалт!|Бүх тулаанд яллаа!) Дахин амжилттай тулалдлаа\.$/, (_, win) => GameLocale.text(win) + ' You cleared the battle again.'],
        [/^Хүлээх утга · (.*)$/, 'Expected · $1'],
        [/^(\d+ \/ \d+) оролтыг шалгаж байна…$/, 'Checking case $1…'],
        [/^(\d+ \/ \d+) оролт зөв\. Зөрсөн утгуудаа харьцуулаарай\.$/, '$1 cases passed. Compare the values that differ.'],
        [/^(\d+ \/ \d+) бодлого давсан$/, '$1 problems solved'],
        [/^Бүх (\d+) оролтод зөв хариуллаа\.$/, 'All $1 cases passed.'],
        [/^Найздаа өгөх код ([0-9a-f]{8})$/i, 'Share this code with your friend: $1'],
        [/^(Цэнхэр робот|Улбар робот) түрүүллээ!$/, (_, side) => GameLocale.text(side) + ' wins!'],
        [/^(\d+)\/3 талбай$/, '$1/3 boards'],
        [/^◆ (\d+) эрдэнэ$/, '◆ $1 gems'],
        [/^(Цэнхэр робот|Улбар робот) · (Та|Хүлээж байна|Давсан|Дуусаагүй)$/, (_, side, status) => GameLocale.text(side) + ' · ' + GameLocale.text(status)],
        [/^(?:Урагш алхав · |Эрдэнэ түүх · |Баруун тийш эргэв · )?Хөл доор эрдэнэ (?:бий|алга) · Урд (?:хана байна|зам чөлөөтэй)$/, line => line.split(' · ').map(value => GameLocale.text(value)).join(' · ')],
        [/^(.+?) · (Цэнхэр робот|Улбар робот) · (\d+)-р багана, (\d+)-р мөр · үлдсэн эрдэнэ (\d+)$/, (_, board, side, x, y, gems) =>
            GameLocale.text(board) + ' · ' + GameLocale.text(side) + ' · column ' + x + ', row ' + y + ' · gems left ' + gems],
        [/^(\d+)-р мөр · (.+)$/, (_, line, error) => 'Line ' + line + ' · ' + GameLocale.text(error)],
        [/^(.+) · Улаанбаатарын цагаар$/, '$1 · Ulaanbaatar time'],
        [/^(Өнөөдөр|Энэ сар) · Тэргүүлэгчид$/, (_, period) => GameLocale.text(period) + ' · Leaders']
